CREATE TABLE IF NOT EXISTS case_resolution_state (case_id uuid PRIMARY KEY REFERENCES recovery_cases(id) ON DELETE CASCADE, user_id text NOT NULL, resolution_status text NOT NULL DEFAULT 'OPEN', phase text NOT NULL DEFAULT 'UNDERSTANDING', next_action_type text NOT NULL DEFAULT 'MONITOR', next_action text NOT NULL, needs_user boolean NOT NULL DEFAULT false, due_at timestamptz, last_meaningful_update_at timestamptz NOT NULL DEFAULT now(), summary text, verified_amount numeric(14,2), resolved_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS case_resolution_user_idx ON case_resolution_state(user_id, resolution_status, updated_at DESC);
CREATE INDEX IF NOT EXISTS case_resolution_due_idx ON case_resolution_state(due_at) WHERE due_at IS NOT NULL AND resolution_status='OPEN';